<?php
declare(strict_types=1); require_once __DIR__.'/_helper.php'; home_visit_require_access();
$tapel=home_visit_active_tapel($pdo); $tid=$tapel?(int)$tapel['id']:0;
$q=trim((string)($_GET['q']??'')); $status=(string)($_GET['status']??''); $per=(int)($_GET['per_page']??20); if(!in_array($per,[10,20,50,100],true))$per=20; $page=max(1,(int)($_GET['page']??1));
$where=['hv.tahun_pelajaran_id=?'];$params=[$tid]; if($q!==''){ $where[]='(s.nis LIKE ? OR s.nisn LIKE ? OR s.nama LIKE ? OR hv.alasan LIKE ?)';$l="%$q%";array_push($params,$l,$l,$l,$l);} if(in_array($status,['direncanakan','dilaksanakan','ditunda','dibatalkan'],true)){ $where[]='hv.status=?';$params[]=$status; }
$count=$pdo->prepare('SELECT COUNT(*) FROM home_visit hv JOIN siswa s ON s.id=hv.siswa_id WHERE '.implode(' AND ',$where));$count->execute($params);$total=(int)$count->fetchColumn();$pages=max(1,(int)ceil($total/$per));$page=min($page,$pages);$off=($page-1)*$per;
$st=$pdo->prepare("SELECT hv.*,s.nis,s.nisn,s.nama,g.nama petugas FROM home_visit hv JOIN siswa s ON s.id=hv.siswa_id LEFT JOIN guru g ON g.id=hv.petugas_id WHERE ".implode(' AND ',$where)." ORDER BY COALESCE(hv.tanggal_pelaksanaan,hv.tanggal_rencana) DESC,hv.id DESC LIMIT $per OFFSET $off");$st->execute($params);$rows=$st->fetchAll();
$stats=['total'=>0,'rencana'=>0,'done'=>0,'delay'=>0]; if($tid){foreach(['total'=>'','rencana'=>" AND status='direncanakan'",'done'=>" AND status='dilaksanakan'",'delay'=>" AND status='ditunda'"] as $k=>$x){$s=$pdo->prepare("SELECT COUNT(*) FROM home_visit WHERE tahun_pelajaran_id=?$x");$s->execute([$tid]);$stats[$k]=(int)$s->fetchColumn();}}
$page_title='Home Visit';require_once __DIR__.'/../layouts/header.php';require_once __DIR__.'/../layouts/sidebar.php';
?>
