<div class="hv-grid"><div class="hv-card"><div class="hv-label">TOTAL</div><div class="hv-num"><?=number_format($stats['total'])?></div><small>Tapel aktif</small></div><div class="hv-card"><div class="hv-label">DIRENCANAKAN</div><div class="hv-num"><?=number_format($stats['rencana'])?></div></div><div class="hv-card"><div class="hv-label">DILAKSANAKAN</div><div class="hv-num"><?=number_format($stats['done'])?></div></div><div class="hv-card"><div class="hv-label">DITUNDA</div><div class="hv-num"><?=number_format($stats['delay'])?></div></div></div>
