<div class="table-responsive"><table class="data-table"><thead><tr><th>Tanggal</th><th>Siswa</th><th>Alasan/Tujuan</th><th>Status</th><th>Petugas</th><th>Aksi</th></tr></thead><tbody><?php if(!$rows):?><tr><td colspan="6" class="empty-state">Belum ada data Home Visit.</td></tr><?php else:foreach($rows as $r):?><tr><td><?=e($r['tanggal_pelaksanaan']?:$r['tanggal_rencana']?:'-')?></td><td><strong><?=e($r['nama'])?></strong><br><small><?=e($r['nis'])?> · <?=e($r['nisn']?:'-')?></small></td><td><?=e((string)$r['alasan'])?><br><small><?=e((string)$r['tujuan'])?></small></td><td><span class="hv-status <?=e(home_visit_status_class($r['status']))?>"><?=e(home_visit_status_label($r['status']))?></span></td><td><?=e((string)($r['petugas']??'Belum ditentukan'))?></td><td><a class="btn btn-secondary btn-sm btn-icon-sm" title="Detail home visit" aria-label="Detail home visit" href="<?=BASE_URL?>home_visit/detail.php?id=<?=(int)$r['id']?>"><i class="bi bi-eye" aria-hidden="true"></i></a></td></tr><?php endforeach;endif;?></tbody></table></div>
<?php if($pages>1):?><div class="pagination"><span>Menampilkan <?=$total?($off+1):0?>–<?=min($off+$per,$total)?> dari <?=$total?></span><div><?php if($page>1):?><a class="btn btn-secondary btn-sm" href="?<?=http_build_query(array_merge($_GET,['page'=>$page-1]))?>">‹</a><?php endif;?> <?php if($page<$pages):?><a class="btn btn-secondary btn-sm" href="?<?=http_build_query(array_merge($_GET,['page'=>$page+1]))?>">›</a><?php endif;?></div></div><?php endif;?></div></section></main><?php require_once __DIR__.'/../layouts/footer.php';?>
